import { Icon, type IconName } from "@/registry/p1/internal/icons";
import "./callout.css";

export interface CalloutProps {
  variant: "note" | "info" | "tip" | "warning";
  title: string;
  body: string;
}

const ICON_BY_VARIANT: Record<CalloutProps["variant"], IconName> = {
  note: "lines",
  info: "info",
  tip: "lightbulb",
  warning: "warning",
};

export function CalloutRender({ variant, title, body }: CalloutProps) {
  return (
    <div className="p1-callout p1-block" data-variant={variant}>
      <div className="p1-callout__inner">
        <div className="p1-callout__box">
          <div className="p1-callout__icon-wrap" aria-hidden="true">
            <Icon name={ICON_BY_VARIANT[variant]} className="p1-callout__icon" />
          </div>
          <div className="p1-callout__content">
            {title && <div className="p1-callout__title">{title}</div>}
            <p className="p1-callout__body">{body}</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { CalloutRender, type CalloutProps } from "./callout";
export type { CalloutProps };

export const CalloutBlock: ComponentConfig<CalloutProps> = {
  fields: {
    variant: {
      type: "select" as const,
      options: [
        { label: "Note", value: "note" },
        { label: "Info", value: "info" },
        { label: "Tip", value: "tip" },
        { label: "Warning", value: "warning" },
      ],
    },
    title: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label for the callout. 2–4 words. E.g. Try this, Good to know, Heads up." },
    },
    body: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1–2 sentences of actionable or informative text. Plain prose." },
    },
  },
  defaultProps: {
    variant: "tip",
    title: "Try this",
    body: "Make “preview first” the default. Share the link before you publish — reviewers stop guessing and start seeing.",
  },
  render: CalloutRender,
};

export const meta = defineMeta({
  title: 'Callout',
  description: 'Highlighted aside box with an icon, title, and body text in note/info/tip/warning variants; use to flag important inline content.',
  categories: ["editorial"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-callout__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-narrow);
  padding-inline: var(--p1-space-lg);
}

.p1-callout__box {
  border-radius: var(--p1-radius-card);
  border: 1px solid;
  border-inline-start-width: 4px;
  display: flex;
  gap: var(--p1-space-md);
  padding: var(--p1-space-md);
}

/* Variant colours */
.p1-callout[data-variant="note"] .p1-callout__box {
  background-color: var(--p1-surface-subtle);
  border-color: var(--p1-border);
  border-inline-start-color: var(--p1-fg-muted);
}
.p1-callout[data-variant="info"] .p1-callout__box {
  background-color: color-mix(in oklch, var(--p1-accent) 8%, var(--p1-surface-default));
  border-color: color-mix(in oklch, var(--p1-accent) 25%, var(--p1-border));
  border-inline-start-color: var(--p1-accent);
}
.p1-callout[data-variant="tip"] .p1-callout__box {
  background-color: color-mix(in oklch, var(--p1-success) 8%, var(--p1-surface-default));
  border-color: color-mix(in oklch, var(--p1-success) 25%, var(--p1-border));
  border-inline-start-color: var(--p1-success);
}
.p1-callout[data-variant="warning"] .p1-callout__box {
  background-color: color-mix(in oklch, var(--p1-warning) 12%, var(--p1-surface-default));
  border-color: color-mix(in oklch, var(--p1-warning) 30%, var(--p1-border));
  border-inline-start-color: var(--p1-warning);
}

.p1-callout__icon-wrap {
  align-items: center;
  border-radius: var(--p1-radius-pill);
  display: grid;
  block-size: 2.25rem;
  flex: none;
  inline-size: 2.25rem;
  justify-items: center;
  place-content: center;
}
.p1-callout[data-variant="note"] .p1-callout__icon-wrap {
  background-color: color-mix(in oklch, var(--p1-fg-muted) 15%, transparent);
  color: var(--p1-fg-muted);
}
.p1-callout[data-variant="info"] .p1-callout__icon-wrap {
  background-color: color-mix(in oklch, var(--p1-accent) 15%, transparent);
  color: var(--p1-accent);
}
.p1-callout[data-variant="tip"] .p1-callout__icon-wrap {
  background-color: color-mix(in oklch, var(--p1-success) 15%, transparent);
  color: var(--p1-success);
}
.p1-callout[data-variant="warning"] .p1-callout__icon-wrap {
  background-color: color-mix(in oklch, var(--p1-warning) 20%, transparent);
  color: color-mix(in oklch, var(--p1-warning) 70%, var(--p1-fg-default));
}

.p1-callout__icon {
  block-size: 1.125rem;
  inline-size: 1.125rem;
}

.p1-callout__content { flex: 1; min-inline-size: 0; }
.p1-callout__title {
  color: var(--p1-fg-default);
  font-weight: var(--p1-weight-bold);
  margin-block-end: 0.25rem;
}
.p1-callout__body {
  color: color-mix(in oklch, var(--p1-fg-default) 80%, transparent);
  font-size: 0.9375rem;
  line-height: var(--p1-leading-normal);
  margin: 0;
  text-wrap: pretty;
}

